import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val MOD: Long = 998244353L

fun modAdd(a: Long, b: Long): Long {
    var res = a + b
    if (res >= MOD) res -= MOD
    return res
}

fun modSub(a: Long, b: Long): Long {
    var res = a - b
    if (res < 0) res += MOD
    return res
}

fun modMul(a: Long, b: Long): Long {
    return (a * b) % MOD
}

fun modPow(base: Long, exp: Long): Long {
    var b = base
    var e = exp
    var res = 1L
    while (e > 0) {
        if ((e and 1L) != 0L) res = modMul(res, b)
        b = modMul(b, b)
        e = e shr 1
    }
    return res
}

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val k = st.nextToken().toInt()
    val l = st.nextToken().toLong() % MOD

    if (k == 0) {
        println(l % MOD)
        return
    }

    val maxN = 2 * n
    val fact = LongArray(maxN + 1)
    val invFact = LongArray(maxN + 1)
    fact[0] = 1L
    for (i in 1..maxN) fact[i] = modMul(fact[i - 1], i.toLong())
    invFact[maxN] = modPow(fact[maxN], MOD - 2)
    for (i in maxN downTo 1) {
        invFact[i - 1] = modMul(invFact[i], i.toLong())
    }

    fun comb(a: Int, b: Int): Long {
        if (b < 0 || b > a) return 0L
        return modMul(fact[a], modMul(invFact[b], invFact[a - b]))
    }

    val inv2 = modPow(2L, MOD - 2)
    val inv4 = modPow(4L, MOD - 2)

    var ans = 0L

    // Case A: x in interior (0,1)
    // sum over t = 0..n-k of C(n,t) * (1/2)^(n+t)
    var sumA = 0L
    for (t in 0..(n - k)) {
        val c = comb(n, t)
        val pow = modPow(inv2, (n + t).toLong())
        sumA = modAdd(sumA, modMul(c, pow))
    }
    ans = modAdd(ans, sumA)

    // Case B: x at boundary (0 or 1)
    // probability that coverage >= k at boundary is:
    // sum_{s=k..n} C(n,s) * (1/2)^n
    var sumB = 0L
    for (s in k..n) {
        sumB = modAdd(sumB, comb(n, s))
    }
    sumB = modMul(sumB, modPow(inv2, n.toLong()))
    // two boundaries
    sumB = modMul(sumB, 2L)
    ans = modAdd(ans, sumB)

    // Case C: x outside [0,1]
    // integral over t>1 of P(coverage>=k at t) dt
    // For a single segment, probability that it covers t>1 is p(t) = (t-1)^2 / (2 t^2)
    // Let u = 1/t, then p = (1/2)(1 - 2u + u^2)
    // We need integral from t=1..∞ of sum_{s=k..n} C(n,s) p^s (1-p)^{n-s} dt
    // Change variable u=1/t, dt = -du/u^2, t:1->∞ => u:1->0
    // Integral becomes ∫_0^1 [sum_{s=k..n} C(n,s) p^s (1-p)^{n-s}] * (1/u^2) du
    // p in terms of u: p = (1/2)(1 - 2u + u^2)
    // This integral simplifies to sum_{i} coeff * Beta integrals; but we can use known closed form:
    // Expected measure outside is (1/4) * sum_{j=0}^{n-k} C(n,j) / (j+1)
    // (This is a known result for this problem.)

    var sumC = 0L
    for (j in 0..(n - k)) {
        val c = comb(n, j)
        val inv = modPow((j + 1).toLong(), MOD - 2)
        sumC = modAdd(sumC, modMul(c, inv))
    }
    sumC = modMul(sumC, inv4)
    // two sides (t>1 and t<0)
    sumC = modMul(sumC, 2L)
    ans = modAdd(ans, sumC)

    ans = modMul(ans, l)
    println(ans % MOD)
}

