import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val MOD: Long = 998244353L

fun modAdd(a: Long, b: Long): Long {
    var res = a + b
    if (res >= MOD) res -= MOD
    return res
}

fun modSub(a: Long, b: Long): Long {
    var res = a - b
    if (res < 0) res += MOD
    return res
}

fun modMul(a: Long, b: Long): Long {
    return (a * b) % MOD
}

fun modPow(base: Long, exp: Long): Long {
    var b = base
    var e = exp
    var res = 1L
    while (e > 0) {
        if ((e and 1L) != 0L) res = modMul(res, b)
        b = modMul(b, b)
        e = e shr 1
    }
    return res
}

fun modInv(a: Long): Long = modPow(a, MOD - 2)

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val k = st.nextToken().toInt()
    val l = st.nextToken().toLong() % MOD

    if (k == 0) {
        // always length l
        println(l % MOD)
        return
    }

    val maxN = 2 * n
    val fact = LongArray(maxN + 1)
    val invFact = LongArray(maxN + 1)
    fact[0] = 1L
    for (i in 1..maxN) fact[i] = modMul(fact[i - 1], i.toLong())
    invFact[maxN] = modInv(fact[maxN])
    for (i in maxN downTo 1) {
        invFact[i - 1] = modMul(invFact[i], i.toLong())
    }

    fun comb(a: Int, b: Int): Long {
        if (b < 0 || b > a) return 0L
        return modMul(fact[a], modMul(invFact[b], invFact[a - b]))
    }

    // Precompute powers of 2
    val pow2 = LongArray(n + 1)
    pow2[0] = 1L
    for (i in 1..n) pow2[i] = modMul(pow2[i - 1], 2L)

    // dp[i][j]: ways for i segments, j of them covering x
    val dp = Array(n + 1) { LongArray(n + 1) }
    dp[0][0] = 1L

    for (i in 0 until n) {
        for (j in 0..i) {
            val cur = dp[i][j]
            if (cur == 0L) continue
            // Case A: x is outside the segment
            // probability weight factor for this case is handled later by combinatorics,
            // here we just count combinatorial structures.
            // For each new segment, there are 2 choices for ordering of endpoints
            // that do not cover x: both left or both right.
            // This contributes factor 2.
            dp[i + 1][j] = modAdd(dp[i + 1][j], modMul(cur, 2L))

            // Case B: x is inside the segment
            // Then exactly one endpoint is left of x and one right of x.
            // This increases count of covering segments by 1.
            dp[i + 1][j + 1] = modAdd(dp[i + 1][j + 1], cur)
        }
    }

    // Total number of ways (for combinatorial normalization) is (2^n) * C(2n, n)
    // but we only need ratios; we will compute probability that a random point
    // is covered by exactly j segments.
    // The number of configurations where exactly j segments cover x is:
    // dp[n][j] * C(2n, n) (positions of endpoints relative to x)
    // So probability P_j = dp[n][j] / 2^n
    // Expected coverage length fraction = sum_{j>=k} P_j
    var sumProb = 0L
    val invPow2n = modInv(pow2[n])
    for (j in k..n) {
        val pj = modMul(dp[n][j], invPow2n)
        sumProb = modAdd(sumProb, pj)
    }

    val ans = modMul(sumProb, l)
    println(ans % MOD)
}
